void test_app_start_04(void)
{
    expect_startup();
    snapshot_data.acceleration_valid = true;
    snapshot_data.acceleration.x_g = 1.25f;
    snapshot_data.acceleration.y_g = -2.5f;
    snapshot_data.acceleration.z_g = 0.75f;
    snapshot_data.acceleration_time_ms = 987U;
    snapshot_to_return = &snapshot_data;
    update_event_to_return = RIDE_SPEEDING;
    update_led_to_return = true;
    expect_ready_one_iteration(false, snapshot_to_return, true);

    ride_events_sample_StubWithCallback(sample_callback);
    ride_events_update_StubWithCallback(update_callback);
    ride_events_message_IgnoreAndReturn("speeding");
    display_set_event_Expect("speeding");
    platform_io_log_Expect("EVENT selected: ");
    platform_io_log_Expect("speeding");
    platform_io_log_Expect("\r\n");
    platform_io_log_Expect("LED command ON\r\n");

    if (setjmp(loop_escape) == 0)
    {
        HOST_RUN_BOUNDED(app_start());
    }

    TEST_ASSERT_FALSE(sample_was_null);
    TEST_ASSERT_NOT_NULL(sample_received);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, 1.25f, sample_copy.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, -2.5f, sample_copy.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, 0.75f, sample_copy.z_g);
    TEST_ASSERT_EQUAL_UINT32(987U, sample_copy.time_ms);
    TEST_ASSERT_EQUAL_INT(2, poll_callback_calls);
}

